def quiet_rag_keys(apps, schema_editor):
    """Ключі RAG постійно опитують стрічку бази знань — їм журнал лише змін і помилок."""
    APIKey = apps.get_model("api", "APIKey")
    for key in APIKey.objects.all():
        if "knowledge:read" in (key.scopes or []):
            APIKey.objects.filter(pk=key.pk).update(log_mode="changes")


